public String getValueAsString() throws IOException {
        if (_currToken == null) {
            return null;
        }

        switch (_currToken) {
            case VALUE_STRING:
                return getText();
            case VALUE_NUMBER_INT:
            case VALUE_NUMBER_FLOAT:
                return NumberInput.decodeNumberString(getText());
            case FIELD_NAME:
                return getCurrentName();
            case VALUE_TRUE:
                return "true";
            case VALUE_FALSE:
                return "false";
            case VALUE_NULL:
                return "null";
            default:
                // For other token types, return null
                return null;
        }
    }
